package dev.eugheist.ttmodern;
final class AwakenedAxeAudit {
 static void check(boolean ok,String label){if(!ok)throw new IllegalStateException("TT awakened axe: "+label);}
 static void run(net.minecraft.server.MinecraftServer server){var level=server.overworld();var p=new net.neoforged.neoforge.common.util.FakePlayer(level,new com.mojang.authlib.GameProfile(java.util.UUID.randomUUID(),"AxeAudit"));p.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);var stack=new net.minecraft.world.item.ItemStack(AwakenedAxe.ITEM.get());p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,stack);var root=new net.minecraft.core.BlockPos(5,290,5);p.setPos(5.5,292,5.5);p.setXRot(90);var saved=new java.util.HashMap<net.minecraft.core.BlockPos,net.minecraft.world.level.block.state.BlockState>();var tree=new java.util.ArrayList<net.minecraft.core.BlockPos>();for(int y=0;y<5;y++){var at=root.above(y);tree.add(at);saved.put(at,level.getBlockState(at));level.setBlock(at,net.minecraft.world.level.block.Blocks.OAK_LOG.defaultBlockState(),2);}var birch=root.offset(1,3,0);saved.put(birch,level.getBlockState(birch));level.setBlock(birch,net.minecraft.world.level.block.Blocks.BIRCH_LOG.defaultBlockState(),2);AdvancedToolModes.change(stack);AdvancedToolModes.change(stack);
 java.util.function.Consumer<net.neoforged.neoforge.event.level.BlockEvent.BreakEvent> deny=e->{if(e.getPlayer()==p&&e.getPos().equals(root.above(4)))e.setCanceled(true);};net.neoforged.neoforge.common.NeoForge.EVENT_BUS.addListener(deny);
 try{p.gameMode.destroyBlock(root);check(level.getBlockState(root.above(4)).is(net.minecraft.world.level.block.Blocks.OAK_LOG)&&!AdvancedToolMining.breaking(p),"protected far log terminates without hanging or guard leakage");}finally{net.neoforged.neoforge.common.NeoForge.EVENT_BUS.unregister(deny);tree.forEach(at->level.setBlock(at,net.minecraft.world.level.block.Blocks.OAK_LOG.defaultBlockState(),2));for(var item:level.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new net.minecraft.world.phys.AABB(0,288,0,10,300,10)))item.discard();}
 try{check(p.gameMode.destroyBlock(root)&&tree.stream().allMatch(at->level.getBlockState(at).isAir()),"real tree mode removes all five logs");check(level.getBlockState(birch).is(net.minecraft.world.level.block.Blocks.BIRCH_LOG),"different log species untouched");var drops=level.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new net.minecraft.world.phys.AABB(root).inflate(1));check(drops.stream().filter(e->e.getItem().is(net.minecraft.world.item.Items.OAK_LOG)).mapToInt(e->e.getItem().getCount()).sum()==5,"exactly five native drops with no duplicate center");check(drops.stream().allMatch(e->e.tickCount==20),"original gathered drop age increment");check(AwakenedAxe.ITEM.get().getDestroySpeed(stack,net.minecraft.world.level.block.Blocks.COBWEB.defaultBlockState())==net.minecraft.world.item.Items.SHEARS.getDestroySpeed(stack,net.minecraft.world.level.block.Blocks.COBWEB.defaultBlockState()),"original shears speed floor");var recipe=dev.eugheist.tc4modern.InfusionItemRecipes.all().stream().filter(r->r.key().equals("ICHOR_AXE_GEM")).findFirst().orElseThrow();check(recipe.componentStacks().size()==12&&recipe.componentStacks().get(2).is(FocusResearch.item("elemental_axe"))&&recipe.aspects().getAmount(thaumcraft.api.aspects.Aspect.WATER)==50&&recipe.aspects().getAmount(thaumcraft.api.aspects.Aspect.TREE)==32,"original recipe components/aspects");check(dev.eugheist.tc4modern.InfusionItemRecipes.match(recipe.componentStacks(),new net.minecraft.world.item.ItemStack(KamiTools.AXE.get()),java.util.Set.of("ICHOR_AXE_GEM"))==recipe,"native infusion accepted");System.out.println("TT AWAKENED AXE AUDIT: ALL PASS (real native tree harvest,protected-log termination,species isolation,exact five drops/no duplicate center,drop age,shears speed,infusion)");
 }finally{for(var item:level.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new net.minecraft.world.phys.AABB(0,288,0,10,300,10)))item.discard();saved.forEach((at,state)->level.setBlock(at,state,2));p.discard();}
 }
}
